{
  "@context":"https://schema.org",
  "@graph":[
    {
      "@type":"Dentist",
      "@id":"https://precisiondentistry.com.au/#practice",
      "name":"Precision Dental",
      "url":"https://precisiondentistry.com.au/",
      "telephone":"+61 7 3852 1160",
      "email":"admin@precisiondentistry.com.au",
      "address":{"@type":"PostalAddress","streetAddress":"S13, HQ South Tower, 520 Wickham Street","addressLocality":"Fortitude Valley","addressRegion":"QLD","postalCode":"4006","addressCountry":"AU"},
      "geo":{"@type":"GeoCoordinates","latitude":-27.4530,"longitude":153.0377},
      "paymentAccepted":"Cash, EFTPOS, Visa, Mastercard, American Express",
      "openingHoursSpecification":[
        {"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Wednesday","Thursday"],"opens":"09:00","closes":"18:00"},
        {"@type":"OpeningHoursSpecification","dayOfWeek":"Tuesday","opens":"10:00","closes":"19:00"},
        {"@type":"OpeningHoursSpecification","dayOfWeek":"Friday","opens":"08:00","closes":"17:00"}
      ]
    },
    {
      "@type":"FAQPage",
      "mainEntity":[
        {"@type":"Question","name":"Are you accepting new patients?","acceptedAnswer":{"@type":"Answer","text":"Yes. We welcome new patients of all ages, from young children through to older adults. You can book online at any time or call our team during opening hours."}},
        {"@type":"Question","name":"Where are you located, and is parking available?","acceptedAnswer":{"@type":"Answer","text":"You will find us at S13, HQ South Tower, 520 Wickham Street, Fortitude Valley. Free on-site parking is available for patients for the duration of their appointment."}},
        {"@type":"Question","name":"What are your opening hours?","acceptedAnswer":{"@type":"Answer","text":"We are open Monday, Wednesday and Thursday from 9am to 6pm, Tuesday from 10am to 7pm and Friday from 8am to 5pm. We are closed on weekends."}},
        {"@type":"Question","name":"Do you see dental emergencies?","acceptedAnswer":{"@type":"Answer","text":"Yes. We keep time available for urgent care and will do our best to see you on the day you contact us. If you have severe facial swelling affecting your breathing or swallowing, please call 000 or go to your nearest hospital emergency department."}},
        {"@type":"Question","name":"Can I claim through my health fund?","acceptedAnswer":{"@type":"Answer","text":"We accept most major health funds and process claims on the spot using HICAPS. We are also a preferred provider for Bupa, HCF and CBHS. Your rebate will depend on your fund and level of cover."}},
        {"@type":"Question","name":"I feel nervous about the dentist. Can you help?","acceptedAnswer":{"@type":"Answer","text":"Absolutely. Let us know when you book, and we will allow extra time for your visit. We explain each step before we begin, agree on a signal you can use to pause, and offer happy gas for patients who would like additional support."}}
      ]
    }
  ]
}
